  this.alert('เรียกคิว ' + d.queue_label + (atFront && d.room_to ? ' ที่' + d.room_to.label : ''), 'success');
  ['visit_unit', 'visit_room'].forEach((n) => {
    const f = this.getFieldRef(n);
    if (f && f.getFieldEditor()) f.getFieldEditor().handleRefresh();
