// เซ็ตคนไข้ + โหลด BMI — ให้ปุ่ม EMR / onMounted เรียกตัวนี้แทนเซ็ต tran ตรง
s.setTran = (row) => {
  s.tran = row; s.loadBmi(); s.loadVs(); s.tickExam()
  // ยังไม่เลือกผู้ป่วย → ซ่อนโซน SOAP ทั้งแถบ (container hide แค่ซ่อน ไม่ล้างค่า field)
  const box = field.getFieldRef('emr_box')
  if (box) { row ? box.show() : box.hide() }
  // เซ็ต visit id ลง field vid + refresh consult — หน่วง 1 tick กันเคส mount แรกที่ field ยังไม่ register
    // เซ็ต visit id ลง field vid + refresh consult + registry — หน่วง 1 tick กันเคส mount แรกที่ field ยังไม่ register
  setTimeout(() => {
    const vidVal = (row && row.vid && row.vid.value) ? String(row.vid.value) : ''
    const f = field.getFieldRef('vid')
    if (f) f.setValue(vidVal)
    const cs = field.getFieldRef('consult_box')
    if (cs && cs.vueState && cs.vueState.load) cs.vueState.load(vidVal || null)

      const cbn = field.getFieldRef('consult_banner')
      if (cbn) {
        if (cbn.vueState && cbn.vueState.load) cbn.vueState.load(row || null)
        // ซ่อน field ทั้งอันถ้าไม่มี consult ฝั่งรับ (clinic===unit_to) — กันช่องว่าง
        const ci = row && row.consult_info
        const showBanner = !!(ci && ci.clinic && row.unit_to && String(ci.clinic) === String(row.unit_to.value))
        showBanner ? cbn.show() : cbn.hide()
      }


    // refresh Disease Registry — person id อยู่ที่ vid.xtbxlv1_xfx_id (= pid.value ของ visit)
    const rg = field.getFieldRef('registry_card')
    if (rg && rg.vueState && rg.vueState.load) {
      const personId = (row && row.vid && row.vid.xtbxlv1_xfx_id) ? String(row.vid.xtbxlv1_xfx_id) : null
      rg.vueState.load(personId, (row && row.vid && row.vid.pid) || null, vidVal || null)
    }

    // ── วางต่อจากบล็อก registry_card ในตัว setTimeout เดิม ──────────────────
    // refresh การ์ดใบสั่งยา — ส่ง tran ไปด้วย เพราะการ์ดใช้ประกอบ patient context ตอนเปิดจอสั่งยา
    const oc = field.getFieldRef('order_card');
    if (oc && oc.vueState && oc.vueState.ordLoad) {
    	oc.vueState.ordLoad(vidVal || null, row || null);
    }

    const ic = field.getFieldRef('item_card');
    if (ic && ic.vueState && ic.vueState.itmLoad) {
    	ic.vueState.itmLoad(vidVal || null, row || null);
    }

    // ── วางต่อจากบล็อก item_card ในตัว setTimeout เดิม ──────────────────────
    // ส่งทั้ง tran ไป — การ์ดถอด person _id เอง (row.vid.xtbxlv1_xfx_id) และเอาชื่อไปโชว์กำกับ
    const mh = field.getFieldRef('m_history');
    if (mh && mh.vueState && mh.vueState.mhLoadFromTran) {
    	mh.vueState.mhLoadFromTran(row || null);
    }

    // ── การ์ด "นัดหมาย" (appt_box) ─────────────────────────────────────────
    // 🔴 ต้องมีบรรทัดนี้ ไม่งั้นเปลี่ยนคนไข้แล้วการ์ดค้างอยู่ที่คนเดิม
    //    (onMounted อ่าน $examTran ได้แค่ตอน mount ครั้งแรกเท่านั้น)
    // 🔴 ส่ง row ทั้งก้อน (ท่าเดียวกับ ordLoad/itmLoad) ไม่ใช่แค่ hn —
    //    ปุ่ม ＋ นัดหมาย ต้องส่ง person _id ต่อให้ฟอร์มนัด จะได้ไม่ต้องค้นคนไข้จาก HN
    //    (hn ไม่ unique ใน zdata_person ⇒ ค้นแล้วอาจได้คนละคน)
    const ap = field.getFieldRef('appt_box');
    if (ap && ap.vueState && ap.vueState.aptLoad) {
    	ap.vueState.aptLoad(vidVal || null, row || null);
    }


    /* ts-hook */
    const tsx = field.getFieldRef('treat_summary');
    if (tsx && tsx.vueState && tsx.vueState.tsLoadFromTran) {
        tsx.vueState.tsLoadFromTran(row || null);
    }
    /* /ts-hook */
