// ---- พิมพ์ใบสรุปการรักษา (OPD Card) — ส่งคลิกต่อให้ปุ่มของ <sd-report> ที่ซ่อนไว้ในเทมเพลต ----
// createReport() เป็น method ภายใน SdReport (เรียกผ่าน userState ไม่ได้) ⇒ ทางเดียวคือกดปุ่มของมัน
// 🔴 ใช้ globalThis.document — `document` ตัวเปล่าถูก shadow เป็น undefined ใน compileFn (Util.ts · restricted)
s.printOpdCard = () => {
  const doc = globalThis.document
  const host = doc && doc.getElementById('pcard-print-host')
  const btn = host && host.querySelector('button')
  if (!btn) { field.alert('ยังเปิดใบสรุปไม่ได้ — ยังไม่มีข้อมูลการมาตรวจ', 'warning'); return }
