options.onCreated:
const s = this.vueState
const field = this
const BOOKING_FORM = '6a8c472df851000f28e50229'    // APPT Booking (form_db) — เปิด readonly เท่านั้น
/* ＋ นัดหมาย เปิดตัวนี้ — ฟอร์มนัดของหมอ ไม่มีแท็บอื่น ไม่มีขั้นค้นผู้ป่วย
   🔴 เปลี่ยนจากจอ N ทั้งจอเมื่อ 02/09 (รุ่นพี่ตีกลับ: เปิดมาแล้วมีแท็บของพยาบาลติดมาด้วย) */
const DOCTOR_BOOKING = '6a97b33a422c1ca959829fe1'

/* 🔴 ทุกคีย์ขึ้นต้น apt — หน้า EMR มีการ์ดหลายใบ ชื่อชนกันแล้วเขียนทับกันเงียบ ๆ
   (การ์ด item_card ของทีมเขาใช้ itm* ด้วยเหตุผลเดียวกัน) */
s.aptList = []
s.aptLoading = false
s.aptErr = ''
s.aptVid = ''
/* ตัวคนไข้ที่ส่งต่อให้ฟอร์มนัด — มาจาก tran ของ opd_card ทั้งชุด
   🔴 `aptPid` คือ person _id (`row.vid.xtbxlv1_xfx_id`) ไม่ใช่ `pid.value`
      ตัวเดียวกับที่ registry_card ใช้ · appt-staff-book หา zdata_person ด้วย _id ตัวนี้ตรง ๆ
   🔴 ส่ง pid ไปแทนการให้ฟอร์มค้นจาก hn — `hn` ไม่ unique ใน zdata_person (เจอจริง 3 แถวต่อ HN)
      ค้นด้วย hn แล้วเจอหลายแถว = มีโอกาสลงนัดให้เด็กผิดคน */
s.aptPid = ''
s.aptHn = ''
s.aptName = ''
s.aptPhone = ''
s.aptAll = false
s.aptToggle = () => { s.aptAll = !s.aptAll }

s.aptDead = (b) => b.status === 'cancelled' || b.status === 'no_show'
/* สรุปบนหัวแถว — นับเฉพาะใบที่ยังรอพยาบาลยืนยัน (ท่าเดียวกับ waitCount() ของ consult) */
s.aptWait = () => (s.aptList || []).filter((b) => !b.status || b.status === 'pending').length
s.aptStatus = (b) => b.status === 'confirmed' ? { color: 'success', label: 'ยืนยันแล้ว' }
  : b.status === 'checked_in' ? { color: 'success', label: 'มาตามนัด' }
  : b.status === 'cancelled' ? { color: 'danger', label: 'ยกเลิก' }
  : b.status === 'no_show' ? { color: 'danger', label: 'ไม่มา' }
  : b.status === 'moved' ? { color: 'info', label: 'เลื่อนแล้ว' }
  : { color: 'warning', label: 'รอยืนยัน' }

s.aptClinic = (b) => { const c = b.clinic || {}; return c.label || c.value || '' }
// วันไทยแบบสั้น — หมอต้องรู้ว่านัดวันไหนจากการกวาดตาแถวเดียว
s.aptWhen = (b) => {
  const p = String(b.slot_date || '').split('-')
  if (p.length !== 3) return String(b.slot_date || '')
  const M = ['','ม.ค.','ก.พ.','มี.ค.','เม.ย.','พ.ค.','มิ.ย.','ก.ค.','ส.ค.','ก.ย.','ต.ค.','พ.ย.','ธ.ค.']
  return Number(p[2]) + ' ' + (M[Number(p[1])] || '') + ' ' + ((Number(p[0]) + 543) % 100)
}

s.aptRows = () => {
  const st = { pending: 0, confirmed: 1, checked_in: 2, moved: 3, no_show: 4, cancelled: 5 }
  const sorted = [...(s.aptList || [])].sort((a, b) =>
    ((st[a.status] ?? 9) - (st[b.status] ?? 9)) ||
    String(a.slot_date || '').localeCompare(String(b.slot_date || '')))
  return s.aptAll ? sorted : sorted.slice(0, 3)
}

/* 🔴 กรองด้วย `from_visit` = visit ที่หมอเปิดอยู่ **ไม่ใช่** `visit_id`
   from_visit = visit วันที่สั่งนัด (วันนี้) · visit_id = visit วันที่ผู้ป่วยมาตามนัด (อนาคต)
   ใช้ผิดตัว = ใบหลุดจากการ์ดทันทีที่ promote สำเร็จ
   เก็บเป็น objectid ⇒ ต้อง CONVERT ก่อนเทียบ เหมือนที่ consult ทำกับ vid.value */
/* arg2 = `tran` ทั้งก้อนจาก opd_card (ท่าเดียวกับ ordLoad/itmLoad ของทีมเขา)
   🔴 รับ string ได้ด้วยเพื่อความเข้ากันได้ย้อนหลัง — ถ้าหน้า EMR ยังเป็นรุ่นที่ส่งแต่ hn มา
      การ์ดจะยังแสดงรายการได้ปกติ แต่ปุ่ม ＋ จะไม่มี pid ⇒ ฟอร์มนัดจะบอกให้เปิดใหม่
      (ยอมให้ตันดีกว่ายอมให้ค้นเอง — ค้นเองคือทางที่ลงนัดผิดคนได้) */
s.aptLoad = (visitId, tran) => {
  s.aptVid = visitId ? String(visitId) : ''
  if (typeof tran === 'string') { if (tran) s.aptHn = tran }
  else if (tran && tran.vid) {
    const v = tran.vid; const pd = v.pid || {}
    s.aptPid = v.xtbxlv1_xfx_id ? String(v.xtbxlv1_xfx_id) : ''
    s.aptHn = String(pd.hn || '')
    /* 🔴 `pid` ไม่มีคีย์ชื่อเต็มสักตัว — ไม่มีทั้ง label / patient_name / name
       ของจริงมีแค่ prename{value,label} · p_fname · p_lname (ตรวจ zdata_visit_tran 02/09)
       รอบแรกผมเดาว่ามี .label แล้วชื่อออกมาว่างบนจอ โดยที่ HN มาปกติ ⇒ ดูเหมือนทำงานอยู่
       ประกอบเองแบบเดียวกับที่ vid.label ของเขาแสดง: คำนำหน้าติดชื่อ ไม่เว้นวรรค */
    const nm = String(pd.p_fname || '') + (pd.p_lname ? ' ' + pd.p_lname : '')
    s.aptName = nm ? ((pd.prename && pd.prename.label) || '') + nm : ''
    /* เบอร์ไม่มีใน pid เลย — ปล่อยว่างถูกแล้ว appt-staff-book หยิบจากเวชระเบียนเอง */
  }
  s.aptErr = ''
  globalThis.__apptCardReload = () => s.aptReload()   // ฟอร์มนัดเรียกกลับหลังจองสำเร็จ
  if (!s.aptVid) { s.aptList = []; return }
  s.aptLoading = true
  try {
    field.getFormRef().userState.crudGetAll({
      sdProvider: {
        providerId: BOOKING_FORM,
        providerType: 'FORM',
        params: { vid: s.aptVid },
        options: {
          where: '`from_visit` = CONVERT(:vid, \'objectId\')',
          orderBy: [{ column: 'slot_date', sort: 'ASC' }],
          limit: 100,
          page: 1
        }
      },
      totalEnable: false
    }, (res) => { s.aptLoading = false; s.aptList = (res && res.data) || [] })
  } catch (e) {
    /* 🔴 พังตรงนี้ต้องพูด — การ์ดว่างเงียบ ๆ แยกไม่ออกจาก 'ไม่มีนัด' */
    s.aptLoading = false
    s.aptErr = 'อ่านรายการนัดไม่สำเร็จ: ' + ((e && e.message) || e)
  }
}
/* 🔴 โหลดซ้ำห้ามส่ง arg2 — ค่าคนไข้ตั้งไว้แล้วตอน setTran ส่ง tran มา
   ส่ง s.aptHn กลับเข้าไปจะไปเข้าสาขา string แล้ว pid/ชื่อ/เบอร์ ที่มีอยู่หายทันที */
s.aptReload = () => s.aptLoad(s.aptVid)

/* ดูใบนัด — เปิดจอ D โหมด view ซึ่งวาดเป็น **ใบนัด** ไม่ใช่ตารางช่องกรอก
   🔴 ของเดิมเปิด APPT Booking แบบ readonly ⇒ หมอเห็น field ดิบ 23 ช่องเรียงกัน
      รุ่นพี่สั่งให้ใช้หน้าตาเดียวกับตอนจองเสร็จ (02/09) และให้ปริ้นท์ได้
   🔴 ยังห้ามเปิด APPT Booking แบบแก้ได้เหมือนเดิม — CRUD ของฟอร์มนั้นยิงแค่ appt-recount
      ซึ่งไม่ใช่ด่าน · เซฟผ่านทางนั้น = ใบไม่มี booking_no · ไม่กันคิวซ้ำ · ไม่ push LINE
   🔴 ไม่มี DOCTOR_BOOKING ⇒ ตกกลับไปเปิดแบบ readonly ของเดิม ยังดูใบได้ ไม่ตัน */
s.aptOpen = (b) => {
  const form = field.getFormRef()
  globalThis.__apptCardClose = () => {
    try { form.subFormClose() } catch (e) { globalThis.console.log('[appt_box] ปิดกล่องไม่สำเร็จ', e) }
    s.aptReload()
  }
  if (!DOCTOR_BOOKING) {
    form.openForm(BOOKING_FORM, String(b._id), s.aptVid, null, {
      readonly: true,
      afterSaveCallback: () => { form.subFormClose(); s.aptReload() }
    })
    return
  }
  form.openForm(DOCTOR_BOOKING, null, s.aptVid, {
    mode: 'view', booking_no: b.booking_no,
    pid: s.aptPid, hn: s.aptHn, patient_name: s.aptName, from_visit: s.aptVid
  }, {
    afterSaveCallback: () => { form.subFormClose(); s.aptReload() }
  })
}

/* ＋ นัดหมาย — เปิดฟอร์มนัดของหมอ ซึ่งจองผ่าน appt-staff-book (ด่านครบ: กันคิวซ้ำ · โควตา · push LINE)
   arg3 = parentId · arg4 = formData — พิสูจน์ 01/09 ด้วย gen-openform-params.js
   🔴 ส่ง pid ไปด้วยเสมอ — ฟอร์มนัดจะได้ไม่ต้องค้นคนไข้เอง (ดูเหตุผลที่ s.aptPid)
   🔴 ไม่ผ่าน CRUD ⇒ afterSaveCallback ไม่ยิง · ฟอร์มนัดเรียก __apptCardReload() กลับมาเอง
      ที่ยังใส่ไว้เพราะไม่มีผลเสีย และเป็นตาข่ายถ้าวันหนึ่งฟอร์มเซฟผ่านแพลตฟอร์มจริง */
s.aptNew = () => {
  if (!s.aptVid) { field.alert('ยังไม่ได้เลือกคนไข้', 'warning'); return }
  if (!DOCTOR_BOOKING) {
    /* 🔴 ยังไม่ได้ import ฟอร์มนัด — บอกตรง ๆ ดีกว่าเปิดกล่องเปล่าให้งง
       และห้ามตกกลับไปเปิดจอ N แทน (นั่นคือของที่ถูกตีกลับ) */
    field.alert('ยังไม่ได้ติดตั้งฟอร์มนัดหมาย (APPT Doctor Booking) — แจ้งผู้พัฒนา', 'warning')
    return
  }
  const form = field.getFormRef()
  /* 🔴 แขวนตัวปิดไว้ให้จอลูกเรียกกลับ — `subFormClose()` เป็นเมธอดของ **ฝั่งที่เปิด**
     ไม่ใช่ของฟอร์มที่ถูกเปิด · จอลูกเรียก getFormRef().subFormClose() เองแล้วไม่มีอะไรเกิดขึ้น
     (พิสูจน์บนเครื่องจริง 02/09: จองผ่าน แต่ปุ่ม ปิด/ยกเลิก กดไม่ติด)
     ท่าเดียวกับ __apptCardReload ที่ใช้ได้อยู่แล้ว */
  globalThis.__apptCardClose = () => {
    try { form.subFormClose() } catch (e) { globalThis.console.log('[appt_box] ปิดกล่องไม่สำเร็จ', e) }
    s.aptReload()
  }
  form.openForm(DOCTOR_BOOKING, null, s.aptVid, {
    pid: s.aptPid, hn: s.aptHn, patient_name: s.aptName, phone: s.aptPhone,
    from_visit: s.aptVid, mode: 'followup'
  }, {
    afterSaveCallback: () => { form.subFormClose(); s.aptReload() }
  })
}

