// แท็บ EMR เป็น lazy — mount แรกอ่าน visit จาก $examTran (ท่าเดียวกับ item_card/consult_box)
const field = this
setTimeout(() => {
  const form = field.getFormRef()
  const tran = (form && form.$examTran) || {}
  const vid = tran.vid && tran.vid.value
  if (!vid) globalThis.console.log('[appt_box] ยังไม่มี visit — $examTran keys =', Object.keys(tran))
  /* 🔴 ส่ง $examTran ทั้งก้อน ไม่ใช่แค่ hn — ปุ่ม ＋ ต้องได้ person _id ไปด้วย
     `$examTran` มีรูปเดียวกับ `tran` ที่ setTran ส่งมา (ทั้งคู่มี .vid) ⇒ ใช้สาขาเดียวกันได้ */
  field.vueState.aptLoad(vid ? String(vid) : '', tran)
}, 0)

