  var my = ++hospSeq;
  callProc(PROC.hospitalSearch, { q: q }).then(function (out) {
    if (my !== hospSeq) return;
    S.rfoHRows = (out && out.rows) || [];
    S.rfoHHas = S.rfoHRows.length > 0;
  }).catch(function () { if (my === hospSeq) { S.rfoHRows = []; S.rfoHHas = false; } });
