function hospPick(code) {
  for (var i = 0; i < S.rfoHRows.length; i++) {
    if (String(S.rfoHRows[i].hcode) === String(code)) {
      setDest(code, S.rfoHRows[i].name);
      destFromIn = false;
      break;
    }
  }
  S.rfoHq = ''; S.rfoHRows = []; S.rfoHHas = false;
