  if (dlgPid !== S.rfoPid) { S.rfoDlgErr = 'ผู้ป่วยในหน้าเปลี่ยนไปแล้ว — ปิดหน้าต่างแล้วเปิดใหม่'; return; }
  var miss = [];
  if (!S.rfoHasDest) miss.push('โรงพยาบาลปลายทาง');
  if (!s(S.rfoDx)) miss.push('Dx ล่าสุด');
  if (!s(S.rfoReason)) miss.push('เหตุผลที่ส่ง');
  if (miss.length) { S.rfoDlgErr = 'ยังไม่ได้กรอก: ' + miss.join(' · '); return; }

  var payload = {
    dest_hcode: S.rfoDestCode, dest_hname: S.rfoDestName, dest_ward: s(S.rfoWard),
    dx_text: s(S.rfoDx), refer_reason: s(S.rfoReason), origin_doctor_phone: s(S.rfoPhone),
  };
  var req = S.rfoIsNew
    ? { action: 'create', pid: dlgPid, direction: S.rfoDir, from_case_no: S.rfoDir === 'back' ? s(S.rfoFrom) : '', payload: payload }
    : { action: 'save', case_no: S.rfoCaseNo, payload: payload };
  S.rfoSaving = true; S.rfoDlgErr = '';
  S.rfoSubmitText = S.rfoIsNew ? 'กำลังเปิดเคส…' : 'กำลังบันทึก…';
