    if (!okOf(out)) { S.rfoDlgErr = (out && out.message) || 'บันทึกไม่สำเร็จ'; return; }
    S.rfoDlgOn = false;
    loadList();
  }).catch(function (e) {
    S.rfoSaving = false;
    S.rfoSubmitText = S.rfoIsNew ? 'เปิดเคสส่งให้ศูนย์' : 'บันทึก';
    S.rfoDlgErr = errText(e);
  });
}

function onAct(act, t) {
  if (act === 'new') { openNew(); return; }
  if (act === 'open') { openCase(t.getAttribute('data-no')); return; }
  if (act === 'reload') { loadList(); return; }
  if (act === 'hist') { S.rfoHistOn = !S.rfoHistOn; paintHist(); return; }
  if (act === 'close') { if (!S.rfoSaving) S.rfoDlgOn = false; return; }
  if (act === 'submit') { submit(); return; }
  if (act === 'dir') { if (S.rfoIsNew) setDir(t.getAttribute('data-v')); return; }
  if (act === 'dest_pick') { if (S.rfoEdit) hospPick(t.getAttribute('data-v')); return; }
  if (act === 'dest_clear') { if (S.rfoEdit) { setDest('', ''); destFromIn = false; } return; }
}
function onInput(k) {
  if (k === 'rfoHq') { hospFind(); return; }
  if (k === 'rfoFrom') { fillFromInbound(); return; }
}
function onEnter(k) { if (k === 'rfoHq') hospFind(); }
function onBootFail(msg) { if (S) S.rfoErr = msg; }

function onBoot() {

  globalThis.clearInterval(globalThis['__apptAutoT_refe']);
  S.rfoLoad = function (vid, tran) {
    try { applyTran(parseTran(tran)); } catch (e) { LOG('rfoLoad พัง ' + (e && e.message)); }
  };
  globalThis.__referEmrCard = { update: function (next) { try { applyTran(parseTran(next)); } catch (e) { LOG('update พัง ' + (e && e.message)); } } };
  paintList();
  var f = getF();
  applyTran(parseTran((f && f.$examTran) || null));
}

