var LOG = function (m) { try { globalThis.console.log('[REFER:' + WRAP_CLASS + '] ' + m); } catch (e) {   } };
var S = null;

function getUS() {
  try {
    var fr = (SELF && typeof SELF.getFormRef === 'function') ? SELF.getFormRef() : null;
    if (fr && fr.userState && typeof fr.userState.runProcess === 'function') return fr.userState;
  } catch (e) {   }
  try {
    var g = SELF && SELF.globalUserState;
    if (g && typeof g.runProcess === 'function') return g;
  } catch (e) {   }
  return null;
}
function getF() {
  try { return (SELF && typeof SELF.getFormRef === 'function') ? SELF.getFormRef() : null; } catch (e) { return null; }
}

function callProc(id, params) {
  return new Promise(function (resolve, reject) {
    if (!id) { reject(new Error('ยังไม่ได้ตั้งค่า process นี้ — แจ้งผู้ดูแลระบบ')); return; }
    var api = getUS();
    if (!api) { reject(new Error('เชื่อมต่อกับระบบไม่ได้ กรุณาเปิดหน้าใหม่')); return; }
    try {

      api.runProcess(id, params || {},
        function (res) { resolve((res && res.data) || {}); },
        function (err) {
          try {
