		vn: visit.vn || '',
		visit_type: typeof cs.serviceTypeLabel === 'function' ? cs.serviceTypeLabel() : '',
		visit_datetime: typeof cs.visitTime === 'function' ? cs.visitTime() : visit.visit_date || '',
		visit_clinic: (visit.visit_clinic || {}).label || '',
		visit_doctor: (visit.visit_doctor || {}).label || '',
		dx_summary: '',
		weight: bmi.weight == null ? '' : bmi.weight,
		height: bmi.stature == null ? '' : bmi.stature, // 🔴 ฟอร์ม BMI ใช้ชื่อ stature ไม่ใช่ height
		bmi: bmi.bmi == null ? '' : bmi.bmi,
		bsa: bmi.bsa == null ? '' : bmi.bsa,
		bp: vital(bpValue, bpLevel),
		pr: vital(vs.pulse, lvl('pulse')),
		temp: vital(vs.temp, lvl('temp')),
		rr: vital(vs.rr, lvl('rr')),
		service_type: 'med',
		inscl_hos: Array.isArray(visit.inscl_hos) ? visit.inscl_hos : [],
	};
};

/* เปิดจอสั่งยา — extra = { order_id } เมื่อเป็นการกลับเข้าไปแก้ใบเดิม

   🔴 refresh เฉพาะตอนที่ "ใบเปลี่ยนจริง" เท่านั้น (พี่แจ้ง 2026-08-04)
      cancelCallback เป็นทางออกทางเดียวของ popup — ทั้ง "กดปิดเฉย ๆ" และ "บันทึกแล้วปิด"
      (จอกด closePopup() ซึ่งวิ่งผ่าน cancelCallback ชุดนี้ · SdFormRender:1060) ⇒ ตัวมันเองแยกไม่ออก
      ⇒ ให้ "จอ" เป็นคนบอกผ่าน callback ที่ฝากไปกับ params — เปิดแล้วปิดเฉย ๆ จึงไม่ยิง process ฟรี
      (function ผ่าน params ได้จริง: formParams/vueParams เป็น shallow spread ทั้งคู่ ไม่ได้ clone ทิ้ง) */
const openScreen = (ctx, extra) => {
	const form = field.getFormRef();
	s.ordDirty = false;
	form.openForm(DRUG_ORDER_FORM_ID, '', String(ctx.visit_id), null, {
		backdrop: false, // ใบยาว — กดพลาดนอกกล่องแล้วปิดทิ้ง = เสียของที่เลือกไว้
		// 🔴 ต้อง spread formParams ของแม่ ไม่งั้น popup ไม่เหลือ _id/xsitex/xunitx (ระบบใช้ตัดสิน site/unit)
		params: Object.assign({}, form.formParams, ctx, extra || {}, {
			// จอเรียกตัวนี้เมื่อ "แตะใบใน DB แล้ว" (บันทึกสำเร็จ หรือหัวใบเกิดแล้วรายการล้มกลางทาง)
			on_order_saved: () => {
				s.ordDirty = true;
			},
		}),
		// 🔴 ใส่ cancelCallback เอง = ทับ default ⇒ ต้อง subFormClose() เองด้วย
		cancelCallback: () => {
			form.subFormClose();
			if (!s.ordDirty) return; // ปิดเฉย ๆ — รายการในการ์ดยังตรงกับ DB อยู่แล้ว
			s.ordDirty = false;
			s.ordReload();
		},
	});
};

// ปุ่ม "+ สั่งยา" ที่หัวการ์ด — เปิดจอเปล่าเพื่อออกใบใหม่
s.ordNew = () => {
	const ctx = ptContext();
	if (!ctx || !ctx.visit_id) {
		field.alert('ยังไม่ได้เลือกผู้ป่วย/visit', 'warning');
		return;
	}
	withInscl(ctx, (full) => openScreen(full, null));
};

// เปิดแก้ใบร่างเดิม — จอจะโหลดรายการกลับเป็นตะกร้าเองจาก order_id (process cpoe-order-get)
s.ordEdit = (o) => {
	if (!o || !o.order_id) return;
	if (!o.can_edit) {
		field.alert('ใบนี้ไม่ใช่ใบร่างแล้ว จึงแก้จากจอสั่งยาไม่ได้', 'warning');
		return;
	}
	const ctx = ptContext();
	if (!ctx || !ctx.visit_id) {
		field.alert('ยังไม่ได้เลือกผู้ป่วย/visit', 'warning');
		return;
	}
	withInscl(ctx, (full) => openScreen(full, { order_id: String(o.order_id) }));
};

/* ส่งใบให้ห้องยา (draft → sent) — process ตัดสินทุกอย่างเอง จอไม่ตัดสินแทน

   🔴 ห้องยาปลายทางไม่ได้เลือกที่นี่ — process หาเองจาก mapping ที่ห้องยาตั้งไว้
      (stock_location.serve_units ประกาศว่าคลังนั้นรับใบจากคลินิกไหน) ⇒ อย่าเพิ่มช่องให้หมอเลือก
   🔴 คำเตือนระดับ block ที่ตีกลับมา ต้องแปะไว้ในการ์ด ไม่ใช่ alert ที่กดปิดแล้วหาย —
      หมอต้องอ่านได้ว่าติดตัวไหน ระหว่างเปิดจอไปแก้
   🔴 ห้าม `await` ในไฟล์นี้ — ปุ่มเป็น sync handler ⇒ ใช้ callback ของ runProcess เท่านั้น

   ── override (C31) ────────────────────────────────────────────────────
   ติด block แล้ว "แก้ไม่ได้จริง" มีอยู่จริงในทางคลินิก (ไม่มียาแทน · ประวัติแพ้ไม่ชัด)
   ระบบที่บล็อกสนิทจะโดนหาทางอ้อม (สั่งด้วยวาจา/กระดาษ) แล้วไม่เหลือร่องรอยในระบบเลย
   ⇒ ให้ทางออกที่ **บันทึกได้**: กรอกเหตุผล ≥ MIN_OVR ตัวอักษร แล้วยิงซ้ำพร้อม override_reason
   🔴 เกณฑ์ความยาวต้องตรงกับ MIN_OVERRIDE_REASON ใน cpoe-order-send (พี่เคาะ 10 · 2026-08-07)
      เช็คที่จอด้วยเพื่อบอกก่อนกด — ไม่ใช่ให้หมอพิมพ์เสร็จแล้วโดน server ตีกลับ */
const MIN_OVR = 10;
s.ordOvrMin = MIN_OVR; // เทมเพลตอ่านค่านี้ ห้าม hardcode เลขซ้ำในจอ (สองที่หลุดกันเมื่อไหร่ = จอบอกเกณฑ์ผิด)

s.ordOvrLen = () => String(s.ordOvrText || '').trim().length;
// setter แยก — เทมเพลตใช้ :value + @input เหมือนช่องอื่นในระบบ ไม่ใช้ v-model / assignment ใน template
s.ordOvrInput = (v) => {
	s.ordOvrText = String(v == null ? '' : v);
	if (s.ordOvrErr) s.ordOvrErr = ''; // พิมพ์ต่อ = ข้อความ error ของรอบก่อนหมดอายุแล้ว
};

// ปิดกล่องเหตุผล — ใช้ทั้งตอนกดยกเลิกและตอนส่งสำเร็จ
s.ordOvrClose = () => {
	s.ordOvrId = '';
	s.ordOvrText = '';
	s.ordOvrErr = '';
};

/* ยิง process จริง — reason ว่าง = ส่งปกติ · มีค่า = ยืนยันส่งทั้งที่ติด block
   🔴 ไม่ส่ง key override_reason เลยเมื่อไม่มีเหตุผล (backend ถือว่า "ไม่ override" ตามพฤติกรรมเดิม) */
const sendOrder = (id, reason) => {
	const form = field.getFormRef();
	if (!form) return;
	s.ordSending[id] = true;
	s.ordBlocks[id] = [];
	const args = { order_id: id };
	if (reason) args.override_reason = reason;
	form.userState.runProcess(
		SEND_PROC,
		args,
		(res) => {
			s.ordSending[id] = false;
			const d = (res && res.data) || {};
			if (!d.success) {
				// รายการที่ติดกฎห้ามสั่ง — แปะไว้ในการ์ดให้อ่านต่อได้ ส่วนเหตุผลอื่นบอกเป็น alert พอ
				if (Array.isArray(d.blocks) && d.blocks.length) s.ordBlocks[id] = d.blocks;
				if (d.code === 'HAS_BLOCK' || d.code === 'OVERRIDE_REASON_TOO_SHORT') {
					// เปิดกล่องเหตุผลค้างไว้ให้กรอกต่อ — ที่พิมพ์ไปแล้วต้องไม่หาย
					s.ordOvrId = id;
					s.ordOvrErr = d.code === 'OVERRIDE_REASON_TOO_SHORT' ? d.message || '' : '';
					// 🔴 ไม่ ordReload() ตรงนี้ — โหลดใหม่ = ลิสต์ถูกสร้างใหม่ กล่องที่เพิ่งเปิดจะกระพริบ
					return;
				}
				field.alert(d.message || 'ส่งใบสั่งยาไม่สำเร็จ', 'warning');
				s.ordReload(); // สถานะอาจเปลี่ยนไปแล้วจากอีกจอ — ให้การ์ดตรงกับ DB เสมอ
				return;
			}
			s.ordOvrClose();
			field.alert(d.message || 'ส่งใบสั่งยาแล้ว', 'success');
			s.ordReload();
		},
		(err) => {
			s.ordSending[id] = false;
			field.alert('ส่งใบสั่งยาไม่สำเร็จ: ' + ((err && err.message) || err), 'warning');
		},
	);
};

// ปุ่ม "ส่งใบสั่งยา" ปกติ (ผ่าน el-popconfirm)
s.ordSend = (o) => {
	if (!o || !o.order_id) return;
	const id = String(o.order_id);
	if (s.ordSending[id]) return;
	if (String(o.current_status || '') !== 'draft') {
		field.alert('ใบนี้ถูกส่งไปแล้ว', 'warning');
		return;
	}
	s.ordOvrClose(); // กดส่งใหม่ = เริ่มรอบใหม่ เหตุผลของรอบก่อนต้องไม่ติดมา
	sendOrder(id, '');
};

// ปุ่ม "ยืนยันส่งพร้อมเหตุผล" ในกล่อง override
s.ordOvrSubmit = (o) => {
	const id = String((o && o.order_id) || s.ordOvrId || '');
	if (!id || s.ordSending[id]) return;
	const reason = String(s.ordOvrText || '').trim();
	if (reason.length < MIN_OVR) {
		s.ordOvrErr = 'ระบุเหตุผลอย่างน้อย ' + MIN_OVR + ' ตัวอักษร (ตอนนี้ ' + reason.length + ')';
		return;
	}
	s.ordOvrErr = '';
	sendOrder(id, reason);
};

/* ══ ยกเลิก / ลบใบ (C43) ══════════════════════════════════════════════════
   พี่เคาะ 2026-08-09: ใบร่าง = **ลบทิ้ง** (ยังไม่มีใครเห็น ไม่ใช่เหตุการณ์ทางคลินิก)
   ใบที่ส่งแล้ว = **ยกเลิก** คงใบไว้ให้ห้องยาเห็นว่าถูกยกเลิก + บังคับเหตุผล ≥ MIN_CAN
   🔴 เกณฑ์ความยาวต้องตรงกับ MIN_REASON ใน cpoe-order-cancel — เช็คที่จอเพื่อบอกก่อนกด
      ไม่ใช่ปล่อยให้พิมพ์เสร็จแล้วโดน server ตีกลับ (หลักเดียวกับกล่อง override)
   🔴 ปุ่มโผล่ตาม can_delete/can_cancel ที่ process เป็นคนตัดสิน — จอไม่คิดกติกาเอง */
const MIN_CAN = 10;
s.ordCanMin = MIN_CAN;

s.ordCanLen = () => String(s.ordCanText || '').trim().length;
s.ordCanInput = (v) => {
	s.ordCanText = String(v == null ? '' : v);
	if (s.ordCanErr) s.ordCanErr = '';
};

s.ordCanOpen = (o) => {
	if (!o || !o.order_id) return;
	s.ordOvrClose(); // กล่อง override กับกล่องยกเลิกเปิดพร้อมกันไม่ได้ — คนละเจตนาบนใบเดียวกัน
	s.ordCanId = String(o.order_id);
	s.ordCanText = '';
	s.ordCanErr = '';
};

s.ordCanClose = () => {
	s.ordCanId = '';
	s.ordCanText = '';
	s.ordCanErr = '';
};

/* ยิง process — reason ว่าง = ลบใบร่าง · มีค่า = ยกเลิกใบที่ส่งแล้ว
   process ตัดสิน mode เองจากสถานะสดใน DB จอแค่ส่งเจตนาไป (จอกับ DB อาจไม่ตรงกันได้เสมอ) */
const cancelOrder = (id, reason) => {
	const form = field.getFormRef();
	if (!form) return;
	s.ordBusy[id] = true;
	const args = { order_id: id };
	if (reason) args.reason = reason;
	form.userState.runProcess(
		CANCEL_PROC,
		args,
		(res) => {
			s.ordBusy[id] = false;
			const d = (res && res.data) || {};
			if (!d.success) {
				if (d.code === 'REASON_REQUIRED') {
					// ใบกลายเป็น sent ระหว่างที่การ์ดยังโชว์ปุ่มลบ — เปิดกล่องเหตุผลให้กรอกต่อ ไม่ใช่แค่เด้ง alert
					s.ordCanId = id;
					s.ordCanErr = d.message || '';
					return;
				}
				field.alert(d.message || 'ยกเลิกใบไม่สำเร็จ', 'warning');
				s.ordCanClose();
				s.ordReload(); // สถานะจริงเปลี่ยนไปแล้ว — การ์ดต้องตรงกับ DB เสมอ
				return;
			}
			s.ordCanClose();
			field.alert(d.message || 'ยกเลิกใบแล้ว', 'success');
			s.ordReload();
		},
		(err) => {
			s.ordBusy[id] = false;
			field.alert('ยกเลิกใบไม่สำเร็จ: ' + ((err && err.message) || err), 'warning');
		},
	);
};

// ปุ่ม "ลบใบนี้" ของใบร่าง (ผ่าน el-popconfirm — ไม่ต้องกรอกเหตุผล)
s.ordDelete = (o) => {
	if (!o || !o.order_id) return;
	const id = String(o.order_id);
	if (s.ordBusy[id]) return;
	cancelOrder(id, '');
};

// ปุ่ม "ยืนยันยกเลิก" ในกล่องเหตุผลของใบที่ส่งแล้ว
s.ordCanSubmit = (o) => {
	const id = String((o && o.order_id) || s.ordCanId || '');
	if (!id || s.ordBusy[id]) return;
	const reason = String(s.ordCanText || '').trim();
	if (reason.length < MIN_CAN) {
		s.ordCanErr = 'ระบุเหตุผลอย่างน้อย ' + MIN_CAN + ' ตัวอักษร (ตอนนี้ ' + reason.length + ')';
		return;
	}
	s.ordCanErr = '';
	cancelOrder(id, reason);
};

/* สิทธิ์ของวิสิท (D9 ข้อ 1) — joiner `vid` ของ Visit Tran ยังไม่ได้ดึง inscl_hos[] มาให้
   ไม่มีสิทธิ์ = จอคิดเป็นชำระเองทั้งใบ ⇒ อ่านจาก joiner ก่อน ไม่มีค่อย query visit ทีเดียว */
function withInscl(ctx, done) {
	if (Array.isArray(ctx.inscl_hos) && ctx.inscl_hos.length) {
		done(ctx);
		return;
	}
	const form = field.getFormRef();
	form.userState.crudGetAll(
		{
			sdProvider: {
				providerId: VISIT_PROVIDER,
				providerType: 'FORM',
				params: { vid: String(ctx.visit_id) },
				options: { where: "_id = CONVERT(:vid, 'objectId')", limit: 1, page: 1 },
			},
			totalEnable: false,
		},
		(res) => {
			const rec = (res && res.data && res.data[0]) || null;
			ctx.inscl_hos = (rec && rec.inscl_hos) || [];
			done(ctx);
		},
		() => {
			field.alert('อ่านสิทธิ์ของวิสิทไม่สำเร็จ — จอสั่งยาจะคิดเป็นชำระเองทั้งใบ', 'warning');
			done(ctx);
		},
	);
}

s.orderContext = (done) => {
	const ctx = ptContext();
	if (!ctx || !ctx.visit_id) {
		done(null);
		return;
	}
	withInscl(ctx, done);
};

options.onMounted:
const field = this;
const s = this.vueState;
// เคสแท็บ EMR mount หลังกดเลือกคนไข้จากคิวไปแล้ว → opd_card.setTran ยิงไปก่อนที่การ์ดนี้จะเกิด
// ⇒ ดึง tran จาก form เองรอบแรก (pattern เดียวกับ registry_card)
setTimeout(() => {
	const form = field.getFormRef();
	const tran = form && form.$examTran;
	const visitId = tran && tran.vid && tran.vid.value ? String(tran.vid.value) : null;
	s.ordLoad(visitId, tran || null);
}, 0);

options.onCreated:
/**
 * item_card · onCreated — การ์ด "ใบสั่งตรวจ / บริการ" ในหน้า EMR (ฟอร์ม EMR 6a4f64e7f8cdfc54cec16488)
 *
 * หน้าที่: ทางเข้า "สั่งตรวจ" ทั้งหมดของหน้า EMR รวมอยู่ที่การ์ดนี้ที่เดียว
 *   ① ปุ่ม "+ สั่งตรวจ" (ใบใหม่)  ② เห็นใบที่บันทึกไปแล้วของวิสิทนี้  ③ กดกลับเข้าไปแก้ใบร่างเดิม
 * โครงลอกมาจาก order_card (ใบสั่งยา) — คนละใบ คนละจอ คนละแหล่งข้อมูล แต่ flow เดียวกัน
 *
 * 🔴 **ไม่ประกอบ patient context เอง** — เรียก `order_card.vueState.orderContext()`
 *    จุดประกอบ context ต้องมีที่เดียว ไม่งั้นวันหนึ่งสองการ์ดจะส่งค่าให้จอไม่เท่ากัน
 *    ⇒ ต้องแพตช์ order_card ก่อน (sdform/cpoe/emr-order-card-expose-context.patch.js)
 * 🔴 กรองใบด้วย `service_type_code` ไม่ใช่ `service_type` — ตัวหลังเป็น label ("Medicine"/"Lab Test")
 *    ที่ rename ได้ทุกเมื่อ (cpoe-order-list ส่ง code มาให้แล้ว)
 * 🔴 ทุก key ที่เทมเพลตอ้างต้องมีค่าตั้งแต่ตรงนี้ — ขาดตัวเดียว = error box ทั้ง widget
 */

const s = this.vueState;
const field = this;

const ITEM_APP_FORM_ID = '6a927860422c1ca959829d26'; // CPOE Order App (form_ui)
const LIST_PROC = '6a71fe5f29c75d41e9c7e9cb'; // cpoe-order-list (ใช้ตัวเดียวกับการ์ดใบสั่งยา)
const SEND_PROC = '6a757d1bf7bf7668d7673c63'; // cpoe-order-send   (draft → sent)
const CANCEL_PROC = '6a7822e11eb17ebfd41dd4d4'; // cpoe-order-cancel (draft → ลบ · sent → cancelled)
const DRUG_TYPE = 'med'; // ใบยาไม่อยู่ในการ์ดนี้ — ยาแยกใบเสมอ (spec §3.4)

/* ══ state ════════════════════════════════════════════════════════════════ */
s.itmList = [];
s.itmLoading = false;
s.itmErr = '';
s.itmVid = null; // visit _id ปัจจุบัน — เซ็ตผ่าน itmLoad จาก opd_card
s.itmTran = null;
s.itmOpenRow = {};
s.itmDirty = false; // จอสั่งตรวจแตะใบใน DB แล้วหรือยัง — ตัวตัดสินว่าตอนปิด popup ต้องโหลดใหม่ไหม
s.itmSending = {}; // order_id ที่กำลังส่ง — กันกดรัวระหว่างรอ process
s.itmBusy = {}; // order_id ที่กำลังลบ/ยกเลิก — แยกจาก itmSending เพราะเป็นคนละปุ่มบนใบเดียวกัน
s.itmBlocks = {}; // order_id → เหตุที่ส่งไม่ได้ ที่ process ตีกลับมา (แปะในการ์ด ไม่ใช่ alert ที่กดปิดแล้วหาย)
s.itmCanId = ''; // ใบที่กำลังกรอกเหตุผลยกเลิก — ทีละใบเท่านั้น (กล่องสองใบพร้อมกัน = กรอกผิดใบ)
s.itmCanText = '';
s.itmCanErr = '';

/* ══ ป้ายสถานะ ════════════════════════════════════════════════════════════
   🔴 ค่าที่ไม่รู้จักต้องโชว์ค่าดิบ ห้ามแปลงเป็น "ร่าง" — ใบที่สถานะเพี้ยนต้องมองเห็นได้จากจอ */
const STATUS = {
	draft: { label: 'ร่าง', color: 'info' },
	sent: { label: 'ส่งแล้ว', color: 'warning' },
	accepted: { label: 'ห้องตรวจรับแล้ว', color: 'warning' },
	collected: { label: 'เก็บสิ่งส่งตรวจแล้ว', color: 'warning' },
	in_process: { label: 'กำลังตรวจ', color: 'warning' },
	resulted: { label: 'มีผลแล้ว', color: 'success' },
	completed: { label: 'เสร็จสิ้น', color: 'success' },
	cancelled: { label: 'ยกเลิก', color: 'info' },
};
s.itmStatus = (o) => {
	const raw = String((o && o.current_status) || '');
	return STATUS[raw] || { label: raw || '—', color: 'danger' };
};

/* ══ ป้ายชนิดรายการ ═══════════════════════════════════════════════════════
   1 ใบมีได้หลายชนิดปนกัน (spec §3.4) ⇒ กางใบแล้วต้องแยกออกด้วยตาเปล่าว่าบรรทัดไหนเป็นอะไร
   🔴 คำกับสีต้องตรงกับจอสั่งตรวจ (TYPES ใน widget item_screen) — คนละคำสองจอ = คนละของในสายตาหมอ
   🔴 map จาก **code** ไม่ใช่ label: label ในทะเบียนเป็น "Radio Exam"/"Nursing Service" ซึ่ง rename ได้ทุกเมื่อ */
const ITEM_TYPE = {
	lab: { label: 'Lab', color: 'success' },
	xray: { label: 'X-ray', color: 'warning' },
	nurs: { label: 'หัตถการ', color: 'primary' },
	order: { label: 'บริการอื่นๆ', color: 'info' },
	med: { label: 'ยา', color: 'danger' }, // ปกติใบยาไม่เข้าการ์ดนี้ แต่ใบผสมชนิดมีได้ ⇒ ต้องมีคำไว้
};
// ไม่รู้ชนิด (ใบเก่าที่บันทึกก่อนมีช่องนี้) → คืน null = ไม่โชว์ป้าย ดีกว่าโชว์ป้ายเปล่าหรือเดาชนิดให้
s.itmType = (it) => {
	const code = String((it && it.item_type_code) || '');
	if (ITEM_TYPE[code]) return ITEM_TYPE[code];
	const raw = String((it && it.item_type_label) || '').trim();
	return raw ? { label: raw, color: 'info' } : null;
};

s.itmMoney = (n) => '฿' + Number(n || 0).toLocaleString('th-TH', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
// created_at เป็น "YYYY-MM-DD HH:mm:ss" — ใบของวิสิทเดียวกันเกิดวันเดียวกันเกือบเสมอ จึงโชว์แค่เวลา
s.itmTime = (v) => {
	const t = String(v || '');
	return t.length >= 16 ? t.slice(11, 16) + ' น.' : t;
};

s.itmToggle = (id) => {
	const k = String(id);
	// เขียนทั้ง object ใหม่ ไม่แก้ key เดิมในที่ — ให้ Vue เห็นการเปลี่ยนแน่นอน
	const next = {};
	Object.keys(s.itmOpenRow).forEach((x) => {
		next[x] = s.itmOpenRow[x];
	});
	next[k] = !next[k];
	s.itmOpenRow = next;
};

/* ══ โหลดใบของวิสิท ═══════════════════════════════════════════════════════
   เรียกจาก opd_card.setTran (เปลี่ยนคนไข้) · onMounted (เข้าแท็บ EMR ทีหลัง) · หลังปิด popup */
s.itmLoad = (visitId, tran) => {
	s.itmVid = visitId ? String(visitId) : null;
	if (tran !== undefined) s.itmTran = tran || null;
	s.itmList = [];
	s.itmErr = '';
	s.itmOpenRow = {};
	s.itmBlocks = {}; // เหตุที่ส่งไม่ได้ของรอบก่อนต้องหายไปพร้อมรายการเก่า ไม่ค้างทับใบที่แก้แล้ว
	s.itmCanId = ''; // กล่องเหตุผลที่ค้างเปิดอยู่ต้องปิดตาม — ใบเก่าอาจไม่อยู่ในลิสต์ใหม่แล้ว
	s.itmCanText = '';
	s.itmCanErr = '';
	if (!s.itmVid) return;
	const form = field.getFormRef();
	if (!form) return;
	s.itmLoading = true;
	form.userState.runProcess(
		LIST_PROC,
		{ visit_id: s.itmVid },
		(res) => {
			s.itmLoading = false;
			const d = (res && res.data) || {};
			// process ที่ตีกลับด้วย success:false ก็มาทาง callback นี้ ไม่ใช่ errCb — ต้องเช็คเอง
			if (!d.success) {
				s.itmErr = d.message || 'อ่านใบสั่งตรวจไม่สำเร็จ';
				return;
			}
			const all = Array.isArray(d.orders) ? d.orders : [];
			s.itmList = all.filter((o) => String(o.service_type_code || '') !== DRUG_TYPE);
			// ใบร่างที่ยังแก้ได้ = สิ่งที่หมอต้องเห็นก่อน ⇒ กางให้เลยถ้ามีใบเดียว
			if (s.itmList.length === 1 && s.itmList[0].can_edit) s.itmOpenRow[s.itmList[0].order_id] = true;
		},
		(err) => {
			s.itmLoading = false;
			s.itmErr = 'อ่านใบสั่งตรวจไม่สำเร็จ: ' + ((err && err.message) || err);
		}
	);
};

s.itmReload = () => s.itmLoad(s.itmVid, undefined);

/* ══ ส่งใบ / ยกเลิก-ลบใบ ══════════════════════════════════════════════════
   กติกาเดียวกับการ์ดใบสั่งยา (พี่เคาะ 2026-08-09):
     ใบร่าง = **ลบทิ้ง** (ยังไม่มีใครเห็น ไม่ใช่เหตุการณ์ทางคลินิก)
     ใบที่ส่งแล้ว = **ยกเลิก** คงใบไว้ให้ห้องปลายทางเห็นว่าถูกยกเลิก + บังคับเหตุผล ≥ MIN_CAN
   🔴 ปุ่มโผล่ตาม can_edit/can_delete/can_cancel ที่ process เป็นคนตัดสิน — จอไม่คิดกติกาเอง
   🔴 ห้องปลายทางไม่ได้เลือกที่นี่ — process หาเองจาก mapping ที่ห้องนั้นตั้งไว้ */
const MIN_CAN = 10;
s.itmCanMin = MIN_CAN;

/* ส่งใบ — ใบตรวจไม่มีชั้นตรวจยา จึงไม่มีกล่อง "ยืนยันส่งทั้งที่ติดคำเตือน" แบบใบยา
   แต่ process ยังตีกลับได้ด้วยเหตุอื่น (หาห้องปลายทางไม่เจอ ฯลฯ) ⇒ แปะเหตุไว้ในการ์ดให้อ่านต่อได้ */
s.itmSend = (o) => {
	if (!o || !o.order_id) return;
	const id = String(o.order_id);
	if (s.itmSending[id]) return;
	if (String(o.current_status || '') !== 'draft') {
		field.alert('ใบนี้ถูกส่งไปแล้ว', 'warning');
		return;
	}
	const form = field.getFormRef();
	if (!form) return;
	s.itmSending[id] = true;
	s.itmBlocks[id] = [];
	form.userState.runProcess(
		SEND_PROC,
		{ order_id: id },
		(res) => {
			s.itmSending[id] = false;
			const d = (res && res.data) || {};
			if (!d.success) {
				if (Array.isArray(d.blocks) && d.blocks.length) s.itmBlocks[id] = d.blocks;
				field.alert(d.message || 'ส่งใบสั่งตรวจไม่สำเร็จ', 'warning');
				s.itmReload(); // สถานะอาจเปลี่ยนไปแล้วจากอีกจอ — การ์ดต้องตรงกับ DB เสมอ
				return;
			}
			field.alert(d.message || 'ส่งใบสั่งตรวจแล้ว', 'success');
			s.itmReload();
		},
		(err) => {
			s.itmSending[id] = false;
			field.alert('ส่งใบสั่งตรวจไม่สำเร็จ: ' + ((err && err.message) || err), 'warning');
		}
	);
};

/* กล่องเหตุผลยกเลิก — เกณฑ์ความยาวต้องตรงกับ MIN_REASON ใน cpoe-order-cancel
   เช็คที่จอเพื่อบอกก่อนกด ไม่ใช่ปล่อยให้พิมพ์เสร็จแล้วโดน server ตีกลับ */
s.itmCanLen = () => String(s.itmCanText || '').trim().length;
s.itmCanInput = (v) => {
	s.itmCanText = String(v == null ? '' : v);
	if (s.itmCanErr) s.itmCanErr = '';
};
s.itmCanOpen = (o) => {
	if (!o || !o.order_id) return;
	s.itmCanId = String(o.order_id);
	s.itmCanText = '';
	s.itmCanErr = '';
};
s.itmCanClose = () => {
	s.itmCanId = '';
	s.itmCanText = '';
	s.itmCanErr = '';
};

/* ยิง process — reason ว่าง = ลบใบร่าง · มีค่า = ยกเลิกใบที่ส่งแล้ว
   process ตัดสิน mode เองจากสถานะสดใน DB จอแค่ส่งเจตนาไป (จอกับ DB อาจไม่ตรงกันได้เสมอ) */
const cancelOrder = (id, reason) => {
	const form = field.getFormRef();
	if (!form) return;
	s.itmBusy[id] = true;
	const args = { order_id: id };
	if (reason) args.reason = reason;
	form.userState.runProcess(
		CANCEL_PROC,
		args,
		(res) => {
			s.itmBusy[id] = false;
			const d = (res && res.data) || {};
			if (!d.success) {
				if (d.code === 'REASON_REQUIRED') {
					// ใบกลายเป็น sent ระหว่างที่การ์ดยังโชว์ปุ่มลบ — เปิดกล่องให้กรอกต่อ ไม่ใช่แค่เด้ง alert
					s.itmCanId = id;
					s.itmCanErr = d.message || '';
					return;
				}
				field.alert(d.message || 'ยกเลิกใบไม่สำเร็จ', 'warning');
				s.itmCanClose();
				s.itmReload();
				return;
			}
			s.itmCanClose();
			field.alert(d.message || 'ยกเลิกใบแล้ว', 'success');
			s.itmReload();
		},
		(err) => {
			s.itmBusy[id] = false;
			field.alert('ยกเลิกใบไม่สำเร็จ: ' + ((err && err.message) || err), 'warning');
		}
	);
};

// ปุ่ม "ลบใบนี้" ของใบร่าง (ผ่าน el-popconfirm — ไม่ต้องกรอกเหตุผล)
s.itmDelete = (o) => {
	if (!o || !o.order_id) return;
	const id = String(o.order_id);
	if (s.itmBusy[id]) return;
	cancelOrder(id, '');
};

// ปุ่ม "ยืนยันยกเลิก" ในกล่องเหตุผลของใบที่ส่งแล้ว
s.itmCanSubmit = (o) => {
	const id = String((o && o.order_id) || s.itmCanId || '');
	if (!id || s.itmBusy[id]) return;
	const reason = String(s.itmCanText || '').trim();
	if (reason.length < MIN_CAN) {
		s.itmCanErr = 'ระบุเหตุผลอย่างน้อย ' + MIN_CAN + ' ตัวอักษร (ตอนนี้ ' + reason.length + ')';
		return;
	}
	s.itmCanErr = '';
	cancelOrder(id, reason);
};

/* ══ patient context — ยืมของ order_card ═════════════════════════════════
   order_card เป็นเจ้าของฟังก์ชันประกอบ context (ptContext + withInscl) อยู่แล้ว
   ⇒ การ์ดนี้ยืมมาใช้ ไม่ทำชุดของตัวเอง · ถ้ายังไม่ได้แพตช์ ต้องดังพอที่คนจะรู้ว่าต้องทำอะไร */
const contextOf = (done) => {
	const oc = field.getFieldRef('order_card');
	const fn = oc && oc.vueState && oc.vueState.orderContext;
	if (typeof fn !== 'function') {
		field.alert('ยังไม่ได้แพตช์ order_card ให้เปิด orderContext() — ดู sdform/cpoe/emr-order-card-expose-context.patch.js', 'error');
		done(null);
		return;
	}
	fn(done);
};

/* เปิดจอสั่งตรวจ — extra = { order_id } เมื่อเป็นการกลับเข้าไปแก้ใบเดิม

   🔴 refresh เฉพาะตอนที่ "ใบเปลี่ยนจริง" เท่านั้น — cancelCallback เป็นทางออกทางเดียวของ popup
      ทั้ง "กดปิดเฉยๆ" และ "บันทึกแล้วปิด" วิ่งผ่านตัวเดียวกัน ⇒ ให้จอบอกผ่าน on_order_saved
   🔴 ส่งทาง `params` ไม่ใช่ `initData` — form_ui ที่มีแต่ vue-ui ตัด initData ทิ้งใน buildDataModel */
const openScreen = (ctx, extra) => {
	const form = field.getFormRef();
	s.itmDirty = false;
	form.openForm(ITEM_APP_FORM_ID, '', String(ctx.visit_id), null, {
		backdrop: false, // ติ๊กชีทยาว — กดพลาดนอกกล่องแล้วปิดทิ้ง = เสียของที่ติ๊กไว้
		// 🔴 ต้อง spread formParams ของแม่ ไม่งั้น popup ไม่เหลือ _id/xsitex/xunitx (ระบบใช้ตัดสิน site/unit)
		params: Object.assign({}, form.formParams, ctx, extra || {}, {
			// ctx มาจาก order_card ซึ่งตั้ง service_type เป็น 'med' ไว้ให้จอสั่งยา — จอนี้ต้องไม่รับค่านั้น
			// (1 ใบมีได้หลายชนิด ชนิดตัวจริงอยู่ที่รายการ ไม่ใช่ที่ใบ — spec §3.4)
			service_type: '',
			on_order_saved: () => {
				s.itmDirty = true;
			},
		}),
		// 🔴 ใส่ cancelCallback เอง = ทับ default ⇒ ต้อง subFormClose() เองด้วย
		cancelCallback: () => {
			form.subFormClose();
			if (!s.itmDirty) return; // ปิดเฉยๆ — รายการในการ์ดยังตรงกับ DB อยู่แล้ว
			s.itmDirty = false;
			s.itmReload();
		},
	});
};

// ปุ่ม "+ สั่งตรวจ" ที่หัวการ์ด — เปิดจอเปล่าเพื่อออกใบใหม่
s.itmNew = () => {
	contextOf((ctx) => {
		if (!ctx || !ctx.visit_id) {
			field.alert('ยังไม่ได้เลือกผู้ป่วย/visit', 'warning');
			return;
		}
		openScreen(ctx, null);
	});
};

// เปิดแก้ใบร่างเดิม — จอจะโหลดรายการกลับเป็นตะกร้าเองจาก order_id
s.itmEdit = (o) => {
	if (!o || !o.order_id) return;
	if (!o.can_edit) {
		field.alert('ใบนี้ไม่ใช่ใบร่างแล้ว จึงแก้จากจอสั่งตรวจไม่ได้', 'warning');
		return;
	}
	contextOf((ctx) => {
		if (!ctx || !ctx.visit_id) {
			field.alert('ยังไม่ได้เลือกผู้ป่วย/visit', 'warning');
			return;
		}
		openScreen(ctx, { order_id: String(o.order_id) });
	});
};

options.onMounted:
const field = this;
const s = this.vueState;
// เคสแท็บ EMR mount หลังกดเลือกคนไข้จากคิวไปแล้ว → opd_card.setTran ยิงไปก่อนที่การ์ดนี้จะเกิด
// ⇒ ดึง tran จาก form เองรอบแรก (pattern เดียวกับ order_card)
setTimeout(() => {
	const form = field.getFormRef();
	const tran = form && form.$examTran;
	const visitId = tran && tran.vid && tran.vid.value ? String(tran.vid.value) : null;
	s.itmLoad(visitId, tran || null);
}, 0);

buttonsRow.onClick:
const form = this.getFormRef();
const goEmr = (row) => {
  form.$examTran = row;                                  // opd_card อ่านตอน mount แรก (lazy tab)
  const card = form.getFieldRef('opd_card');
  if (card && card.vueState && card.vueState.setTran) card.vueState.setTran(row);

  const tab = form.getFieldRef('main_app');
  if (tab) tab.activeTabName = 'tab_pane_41691';
};
const st = dataRow.vtran_status;
goEmr(dataRow); return;

options.onScan:
// field: scan_code (scan-code-ui) · onScan(value, qty) — ฟอร์ม EMR
// ยิง HN หรือ VN → ค้น visit tran ของ unit ตัวเอง (วันนี้) — กรองด้วย unit_path: เลือกหน่วยแม่ (MP) ค้นได้ทุกคลินิกลูก → เจอ = สลับไปแท็บ EMR + setTran ให้เลย
// mirror กติกาปุ่ม EMR ในแถวคิวทุกข้อ (called → start ก่อน, waiting/skipped → ไม่ให้เข้า)
// 🔴 ชื่อ param ห้ามเป็น prefix ของกันเอง — ที่นี่ใช้ :scancode ตัวเดียวทั้ง 2 ที่ ปลอดภัย
// 🔴 path ที่มีจุด (`vid.vn`, `vid.pid.hn`) ต้องครอบ backtick ไม่งั้น NoQL อ่านเป็น table.column

const TRAN_FORM  = '6a461235e521219e514d1c4b'   // Visit Tran (zdata_visit_tran)
const VISIT_FORM = '6a40fdec4b6dfdf45acbfbce'   // Visit (zdata_visit)
const START_PROC = '6a4f852422f95f21b606d9a3'   // เริ่มตรวจ (action: 'start')
const TODAY_SQL  = "`visit_date` = DATE_TO_STRING(DATE_ADD(CURRENT_DATE(), 'hour', 7), '%Y-%m-%d')"

const form = this.getFormRef()
const api  = form.userState

if (form.showPopupFlag) return   // มีฟอร์มลูกเปิดค้าง → อย่าสลับคนไข้ข้างหลัง dialog

const code = String(value == null ? '' : value).replace(/\D/g, '')
if (!code) { this.notify('อ่านบาร์โค้ดไม่ได้: ' + value, 'warning'); return }

// ── helper: ยิง query แล้วรอผลให้จบทางเดียว (callback/promise แล้วแต่จังหวะ) + กันค้าง 5 วิ ──
const runQuery = (sdProvider) => new Promise((resolve) => {
  let settled = false
  const done = (r) => { if (!settled) { settled = true; resolve(r) } }
  let ret
  try { ret = api.crudGetAll({ sdProvider, totalEnable: false }, (r) => done(r), () => done(null)) }
  catch (e) { done(null); return }
  if (ret && typeof ret.then === 'function') ret.then((r) => { if (r !== undefined && r !== null) done(r) }).catch(() => {})
  setTimeout(() => done(null), 5000)
})
const pickRows = (r) => {
  if (!r) return []
  if (Array.isArray(r)) return r
  if (Array.isArray(r.data)) return r.data
  if (r.data && Array.isArray(r.data.data)) return r.data.data
  if (r.reply && Array.isArray(r.reply.data)) return r.reply.data
  if (Array.isArray(r.rows)) return r.rows
  return []
}

// ── ① ค้น visit tran ทั้ง unit ของเราวันนี้ (ทุกสถานะ รวม done) ด้วย VN หรือ HN ──
// ไม่ระบุ select เพื่อให้ได้ vid.* ที่ join มาครบเหมือนที่ list ส่งให้ปุ่ม EMR (setTran ต้องใช้)
const rows = pickRows(await runQuery({
  providerId: TRAN_FORM,
  providerType: 'FORM',
  options: {
    where: TODAY_SQL + ' AND `unit_path` = :xunit_codex AND (`vid.vn` = :scancode OR `vid.pid.hn` = :scancode)',
    orderBy: [{ column: 'queue_ts', sort: 'DESC' }],
    limit: 10,
  },
  params: { scancode: code },
}))

// ── ② ไม่มีคิว → บอกให้ได้ว่า "ไม่มี visit" หรือ "มี visit แต่คิวพัง" ──
if (!rows.length) {
  const vrows = pickRows(await runQuery({
    providerId: VISIT_FORM,
    providerType: 'FORM',
    options: {
      where: TODAY_SQL + ' AND (`vn` = :scancode OR `pid.hn` = :scancode)',
      select: ['_id', 'vn', 'pid'],
      limit: 3,
    },
    params: { scancode: code },
  }))
  if (vrows.length) {
    const v = vrows[0]
    const p = v.pid || {}
    this.notify('พบ visit VN' + (v.vn || '-') + ' (HN' + (p.hn || '-') + ' ' + ((p.p_fname || '') + ' ' + (p.p_lname || '')).trim() + ') แต่ไม่มีคิวในหน่วยนี้วันนี้', 'warning')
  } else {
    this.notify('ไม่พบ HN/VN ' + code + ' ในระบบวันนี้', 'warning')
  }
  return
}

// ── ③ เลขเดียวไปตรงกับคนละคน (VN ของคนหนึ่ง = HN ของอีกคน) → ไม่เดา ให้เลือกจากคิวเอง ──
const visitIds = []
rows.forEach((r) => {
  const vidVal = r.vid && r.vid.value ? String(r.vid.value) : ''
  if (vidVal && visitIds.indexOf(vidVal) === -1) visitIds.push(vidVal)
})
if (visitIds.length > 1) {
  const who = rows.map((r) => {
    const p = (r.vid && r.vid.pid) || {}
    return 'VN' + ((r.vid && r.vid.vn) || '-') + '/HN' + (p.hn || '-') + ' ' + (p.p_fname || '')
  }).join(' · ')
  this.notify('รหัส ' + code + ' ตรงกับหลายราย: ' + who + ' — กรุณาเลือกจากคิวเอง', 'warning')
  return
}

// ── ④ คนเดียวหลายคิว → ห้องฉันก่อน แล้วสถานะที่กำลังทำอยู่ก่อน ──
const RANK = { in_progress: 4, called: 3, waiting: 2, skipped: 1, done: 0 }
const myRoom = (api.user && api.user.room && api.user.room.code) || ''
const score = (r) =>
  (myRoom && r.room_to && String(r.room_to.value) === String(myRoom) ? 100 : 0) +
  (RANK[r.vtran_status] != null ? RANK[r.vtran_status] : 0)
rows.sort((a, b) => score(b) - score(a) || String(b.queue_ts || '').localeCompare(String(a.queue_ts || '')))
const tran = rows[0]

const pt   = (tran.vid && tran.vid.pid) || {}
const name = ((pt.p_fname || '') + ' ' + (pt.p_lname || '')).trim()
const tag  = 'คิว ' + (tran.queue_label || '-') + ' · HN' + (pt.hn || '-') + ' ' + name

// ── ⑤ เข้า EMR — 3 บรรทัดเดียวกับปุ่ม EMR ในแถวคิว ──
const goEmr = (row) => {
  form.$examTran = row                                   // opd_card อ่านตอน mount แรก (lazy tab)
  const card = form.getFieldRef('opd_card')
  if (card && card.vueState && card.vueState.setTran) card.vueState.setTran(row)
  const tab = form.getFieldRef('main_app')
  if (tab) tab.activeTabName = 'tab_pane_41691'
}
const refreshQueues = () => {
  ;['visit_unit', 'visit_room'].forEach((n) => {
    const ref = form.getFieldRef(n)
    const ed  = ref && ref.getFieldEditor && ref.getFieldEditor()
    if (ed && ed.handleRefresh) ed.handleRefresh()
  })
}

const st = tran.vtran_status

if (st === 'in_progress') { goEmr(tran); this.notify('เข้า EMR ' + tag, 'success'); return }

if (st === 'done') { goEmr(tran); this.notify('เข้า EMR ' + tag + ' — ⚠ คิวนี้ปิดตรวจแล้ว', 'warning'); return }

if (st !== 'called') {
  this.notify('คิวยังไม่ถูกเรียก (สถานะ: ' + (st || '-') + ') — ' + tag, 'warning')
  return
}

// called → เริ่มตรวจให้เหมือนกดปุ่ม EMR แล้วค่อยเข้า
api.runProcess(START_PROC, { tran_id: String(tran._id), action: 'start' }, (res) => {
  const d = res.data || {}
  if (!d.success) { this.alert(d.message || 'เริ่มตรวจไม่สำเร็จ', 'warning'); return }
  this.notify('เริ่มตรวจ ' + tag, 'success')
  refreshQueues()
  // process เพิ่ง stamp start_at ใน DB — tran เป็น snapshot เก่า ต้อง patch ก่อนส่งเข้าการ์ด ไม่งั้น timer ขึ้น --:--
  goEmr({ ...tran, vtran_status: 'in_progress', start_at: this.dayjs().format('YYYY-MM-DD HH:mm:ss') })
}, (err) => this.alert(String((err && err.message) || err), 'error'))

